import json, sys
from pathlib import Path
import numpy as np
from scipy.optimize import minimize
from scipy.signal import find_peaks

root=Path('_scratch/s11c')
def get(folder):
    assert json.loads((folder/'outcome.json').read_text())['exitCode']==0
    assert json.loads((folder/'limit-validation.json').read_text())['verified']
    f=np.load(folder/'trace.npz')
    return dict(zip(f['columns'],f['trace'].T))
def rms(x):return np.sqrt(np.mean(x*x))
def fit(t,y):
    def basis(t,pars):
        w,g=pars
        return np.column_stack((np.exp(-g*t)*np.sin(w*t),np.exp(-g*t)*np.cos(w*t)))
    def err(pars):
        m=basis(t,pars)
        return np.linalg.norm(y-m@np.linalg.lstsq(m,y,rcond=None)[0])/np.linalg.norm(y)
    seeds=[(w,g) for w in np.arange(.35,28,.45) for g in (0,.2,.6,1.)]
    ranked=sorted(seeds,key=err)
    best=min([minimize(err,q,method='L-BFGS-B',bounds=[(.1,30),(0,2)]) for q in ranked[:5]],key=lambda r:r.fun)
    return best.x,best.fun,np.linalg.lstsq(basis(t,best.x),y,rcond=None)[0],basis
for rad in ('half','one','double'):
    result=[get(root/f'shear_release_{rad}_{mesh}_01') for mesh in (26,34)]
    for col in ('near_velocity','far_velocity'):
        for n,z in zip((26,34),result):
            t=z['time']; y=z[col]
            tr=(t>=8)&(t<14); hold=(t>=14)&(t<20)
            q,etrain,c,fn=fit(t[tr]-8,y[tr]); etest=np.linalg.norm(y[hold]-fn(t[hold]-8,q)@c)/np.linalg.norm(y[hold])
            if n==34:
                common=(t>=8)&(t<20)
                yc=np.interp(t[common],result[0]['time'],result[0][col])
                cm=float(np.linalg.norm(y[common]-yc)/np.linalg.norm(y[common]))
            else: cm=None
            print(json.dumps(dict(radius=rad,probe=col,mesh=n,omega=q[0],damping=q[1],train_mismatch=etrain,holdout_mismatch=etest,late_normed_rms=rms(y[hold])/np.max(abs(y)),coarse_fine_rms_mismatch=cm)),flush=True)
